content:
:root {
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "Hiragino Sans", Meiryo, sans-serif;
  --bg-color: #0f172a;
  --bg-card: #1e293b;
  --bg-card-hover: #24344d;
  --border-color: #334155;
  --border-color-light: #475569;
  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --text-muted: #94a3b8;
  --accent-primary: #3b82f6;
  --accent-primary-hover: #2563eb;
  --accent-cyan: #06b6d4;
  --accent-emerald: #10b981;
  --accent-rose: #f43f5e;
  --accent-amber: #f59e0b;
  --positive-bg: rgba(16, 185, 129, 0.15);
  --positive-text: #34d399;
  --negative-bg: rgba(244, 63, 94, 0.15);
  --negative-text: #fb7185;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.25);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.3), 0 2px 4px -2px rgba(0, 0, 0, 0.2);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.4), 0 4px 6px -4px rgba(0, 0, 0, 0.3);
  --transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-color);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* アクセシビリティ・フォーカススタイル */
button:focus-visible,
input:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--bg-card), 0 0 0 4px var(--accent-primary);
}

/* ==========================================================================
   コンテナ・ヘッダー
   ========================================================================== */
.dashboard-container {
  max-width: 1360px;
  margin: 0 auto;
  padding: 24px 20px 48px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.dashboard-header {
  display: flex;
  flex-direction: column;
  gap: 16px;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 20px;
}

@media (min-width: 768px) {
  .dashboard-header {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }
}

.header-title-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.header-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

@media (min-width: 768px) {
  .header-title {
    font-size: 1.75rem;
  }
}

.header-subtitle {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* ==========================================================================
   フィルターバー
   ========================================================================== */
.filter-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  background-color: rgba(30, 41, 59, 0.7);
  padding: 4px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
}

.filter-btn {
  background: transparent;
  border: 1px solid transparent;
  color: var(--text-secondary);
  font-size: 0.8125rem;
  font-weight: 500;
  padding: 6px 14px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  white-space: nowrap;
}

.filter-btn:hover {
  color: var(--text-primary);
  background-color: rgba(255, 255, 255, 0.05);
}

.filter-btn-active {
  background-color: var(--accent-primary);
  color: #ffffff;
  border-color: var(--accent-primary);
  box-shadow: 0 0 12px rgba(59, 130, 246, 0.4);
}

.filter-btn-active:hover {
  background-color: var(--accent-primary-hover);
  color: #ffffff;
}

/* ==========================================================================
   シミュレーションパネル
   ========================================================================== */
.sim-panel {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 16px 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.sim-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--accent-cyan);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}

.sim-title-label {
  display: flex;
  align-items: center;
  gap: 6px;
}

.sim-reset-btn {
  background: transparent;
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  font-size: 0.75rem;
  font-weight: 500;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.sim-reset-btn:hover {
  background-color: rgba(255, 255, 255, 0.05);
  color: var(--text-primary);
  border-color: var(--border-color-light);
}

.sim-controls {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

@media (min-width: 640px) {
  .sim-controls {
    flex-direction: row;
    align-items: center;
    gap: 24px;
  }
}

.sim-slider-group {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 1;
}

.sim-label {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  min-width: 140px;
  white-space: nowrap;
}

.sim-slider {
  flex: 1;
  -webkit-appearance: none;
  appearance: none;
  height: 6px;
  border-radius: 3px;
  background: var(--border-color);
  outline: none;
  transition: background 0.2s;
  cursor: pointer;
}

.sim-slider:focus-visible {
  box-shadow: 0 0 0 2px var(--bg-card), 0 0 0 4px var(--accent-cyan);
}

.sim-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--accent-cyan);
  cursor: pointer;
  box-shadow: 0 0 8px rgba(6, 182, 212, 0.6);
  border: 2px solid #0f172a;
}

.sim-slider::-moz-range-thumb {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--accent-cyan);
  cursor: pointer;
  box-shadow: 0 0 8px rgba(6, 182, 212, 0.6);
  border: 2px solid #0f172a;
}

.sim-input-group {
  display: flex;
  align-items: center;
  gap: 4px;
}

.sim-number-input {
  width: 64px;
  padding: 4px 6px;
  font-size: 0.8125rem;
  font-weight: 500;
  text-align: right;
  color: var(--text-primary);
  background-color: rgba(15, 23, 42, 0.6);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  transition: var(--transition);
}

.sim-number-input:hover {
  border-color: var(--border-color-light);
}

.sim-val-display {
  font-size: 0.875rem;
  font-weight: 700;
  color: var(--text-primary);
  min-width: 60px;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.sim-val-unit {
  font-size: 0.875rem;
  font-weight: 700;
  color: var(--text-primary);
}

/* ==========================================================================
   KPIカードグリッド
   ========================================================================== */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(1, minmax(0, 1fr));
  gap: 16px;
}

@media (min-width: 640px) {
  .kpi-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 1024px) {
  .kpi-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

.kpi-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 12px;
  transition: var(--transition);
}

.kpi-card:hover {
  background-color: var(--bg-card-hover);
  border-color: var(--border-color-light);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.kpi-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.kpi-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.kpi-icon-wrap {
  width: 38px;
  height: 38px;
  border-radius: var(--radius-md);
  background-color: rgba(59, 130, 246, 0.12);
  color: var(--accent-primary);
  display: flex;
  align-items: center;
  justify-content: center;
}

.kpi-value-row {
  display: flex;
  align-items: baseline;
  gap: 6px;
  flex-wrap: wrap;
}

.kpi-value {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}

.kpi-unit {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-muted);
}

.kpi-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 9999px;
  margin-left: auto;
}

.kpi-badge-positive {
  background-color: var(--positive-bg);
  color: var(--positive-text);
  border: 1px solid rgba(16, 185, 129, 0.3);
}

.kpi-badge-negative {
  background-color: var(--negative-bg);
  color: var(--negative-text);
  border: 1px solid rgba(244, 63, 94, 0.3);
}

.kpi-subtext {
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* ==========================================================================
   チャートセクション
   ========================================================================== */
.charts-grid {
  display: grid;
  grid-template-columns: repeat(1, minmax(0, 1fr));
  gap: 20px;
}

@media (min-width: 1024px) {
  .charts-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.chart-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.chart-card-full {
  grid-column: 1 / -1;
}

.chart-title {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
}

.chart-subtitle {
  font-size: 0.75rem;
  color: var(--text-secondary);
  margin-top: 2px;
}

.chart-wrapper {
  width: 100%;
  height: 320px;
  position: relative;
}

/* Recharts ツールチップのオーバーライド */
.recharts-default-tooltip {
  background-color: #1e293b !important;
  border: 1px solid var(--border-color) !important;
  border-radius: var(--radius-md) !important;
  box-shadow: var(--shadow-lg) !important;
  color: var(--text-primary) !important;
  font-size: 0.8125rem !important;
  padding: 10px 14px !important;
}

.recharts-tooltip-item-list {
  padding-top: 4px;
}

.recharts-tooltip-label {
  font-weight: 600;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 4px;
  margin-bottom: 4px;
}

.recharts-cartesian-grid-horizontal line,
.recharts-cartesian-grid-vertical line {
  stroke: #334155;
  stroke-dasharray: 3 3;
}

.recharts-text {
  fill: #94a3b8 !important;
  font-size: 0.75rem;
}

/* ==========================================================================
   実績テーブル
   ========================================================================== */
.table-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 16px;
  overflow: hidden;
}

.table-wrapper {
  width: 100%;
  overflow: hidden;
  overflow-x: auto;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: var(--border-color) transparent;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.875rem;
  white-space: nowrap;
}

.data-table thead {
  background-color: rgba(15, 23, 42, 0.6);
  border-bottom: 1px solid var(--border-color);
}

.th-cell {
  padding: 12px 16px;
  font-weight: 600;
  color: var(--text-secondary);
  font-size: 0.8125rem;
  letter-spacing: 0.03em;
  vertical-align: middle;
}

.th-cell .filter-btn {
  padding: 4px 6px;
  font-size: 0.8125rem;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
}

.th-cell .filter-btn:hover {
  color: var(--text-primary);
  background-color: rgba(255, 255, 255, 0.06);
}

.th-cell.td-num .filter-btn {
  margin-left: auto;
  justify-content: flex-end;
}

.data-table tbody tr {
  border-bottom: 1px solid var(--border-color);
  transition: background-color 0.15s ease;
}

.data-table tbody tr:last-child {
  border-bottom: none;
}

.data-table tbody tr:hover {
  background-color: rgba(255, 255, 255, 0.03);
}

.td-cell {
  padding: 12px 16px;
  color: var(--text-primary);
  font-size: 0.875rem;
  vertical-align: middle;
}

.td-num {
  text-align: right;
  font-variant-numeric: tabular-nums;
  font-weight: 500;
}

.td-highlight {
  font-weight: 600;
}

.td-muted {
  color: var(--text-secondary);
}

/* 達成率プログレスバー補助クラス */
.progress-bar-container {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 120px;
}

.progress-track {
  flex: 1;
  height: 6px;
  background-color: var(--border-color);
  border-radius: 3px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.3s ease;
}

.progress-rate {
  font-size: 0.8125rem;
  font-weight: 600;
  min-width: 42px;
  text-align: right;
}

.progress-rate-positive {
  color: var(--positive-text);
}

.progress-rate-muted {
  color: var(--text-secondary);
}

export interface MonthlyData {
  month: string;
  sales: number;
  customers: number;
  avgSpend: number;
  targetSales: number;
}

export type KpiIconType = 'sales' | 'customers' | 'avgSpend';

export interface SummaryCardData {
  title: string;
  value: string;
  subValue: string;
  changeRate: number;
  isPositive: boolean;
  unit: string;
  iconName: KpiIconType;
}

export type PeriodFilterType = 'all' | 'first-half' | 'second-half' | 'last-3';

export interface FilterOption {
  label: string;
  value: PeriodFilterType;
}

export interface SimulationParams {
  customerRate: number;
  spendRate: number;
}

export type SortKey = 'month' | 'sales' | 'targetSales' | 'customers' | 'avgSpend' | 'achieveRate';
export type SortOrder = 'asc' | 'desc';

import { FC, ReactNode } from 'react';
import { JapaneseYen, Users, ShoppingBag, TrendingUp, TrendingDown } from 'lucide-react';
import { SummaryCardData, KpiIconType } from '../types';

interface KpiCardsProps {
  cards?: SummaryCardData[];
}

const ICON_MAP: Record<KpiIconType, ReactNode> = {
  sales: <JapaneseYen size={20} />,
  customers: <Users size={20} />,
  avgSpend: <ShoppingBag size={20} />,
};

const KpiCards: FC<KpiCardsProps> = ({ cards = [] }) => {
  return (
    <div className="kpi-grid">
      {cards.map((card) => {
        const badgeClass = card.isPositive ? 'kpi-badge kpi-badge-positive' : 'kpi-badge kpi-badge-negative';
        const TrendIcon = card.isPositive ? TrendingUp : TrendingDown;
        const formattedChange = `${card.isPositive ? '+' : ''}${card.changeRate.toFixed(1)}%`;
        const changeLabel = `前期比または目標比 ${card.isPositive ? 'プラス' : 'マイナス'} ${Math.abs(card.changeRate).toFixed(1)}パーセント`;

        return (
          <div key={card.title} className="kpi-card">
            <div className="kpi-card-header">
              <span className="kpi-title">{card.title}</span>
              <div className="kpi-icon-wrap" aria-hidden="true">
                {ICON_MAP[card.iconName] ?? <JapaneseYen size={20} />}
              </div>
            </div>

            <div className="kpi-value-row">
              <span className="kpi-value">{card.value}</span>
              <span className="kpi-unit">{card.unit}</span>
              <div
                className={badgeClass}
                role="status"
                aria-label={changeLabel}
              >
                <TrendIcon size={12} aria-hidden="true" />
                <span>{formattedChange}</span>
              </div>
            </div>

            <div className="kpi-subtext">{card.subValue}</div>
          </div>
        );
      })}
    </div>
  );
};

export default KpiCards;

import { FC } from 'react';
import {
  ResponsiveContainer,
  ComposedChart,
  AreaChart,
  Bar,
  Line,
  Area,
  XAxis,
  YAxis,
  Tooltip,
  Legend,
  CartesianGrid,
} from 'recharts';
import { MonthlyData } from '../types';

interface ChartsViewProps {
  data?: MonthlyData[];
}

const THEME_COLORS = {
  sales: '#3b82f6',
  target: '#f59e0b',
  customers: '#10b981',
  avgSpend: '#06b6d4',
  chartBg: '#0f172a',
} as const;

const ChartsView: FC<ChartsViewProps> = ({ data = [] }) => {
  const formatYAxisSales = (val: number) => {
    if (val >= 1000000) {
      return `${(val / 10000).toLocaleString()}万円`;
    }
    return val.toLocaleString();
  };

  const formatYAxisCustomers = (val: number) => {
    return `${val.toLocaleString()}人`;
  };

  const formatYAxisAvgSpend = (val: number) => {
    return `¥${val.toLocaleString()}`;
  };

  return (
    <div className="charts-grid">
      <div className="chart-card chart-card-full">
        <div>
          <h2 className="chart-title">売上高・客数・目標推移</h2>
          <p className="chart-subtitle">売上実績（棒）、目標売上（点線）、来店客数（折れ線）の複合対比</p>
        </div>
        <div className="chart-wrapper">
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart data={data} margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} />
              <XAxis dataKey="month" tickLine={false} />
              <YAxis
                yAxisId="salesAxis"
                orientation="left"
                tickFormatter={formatYAxisSales}
                tickLine={false}
                axisLine={false}
              />
              <YAxis
                yAxisId="custAxis"
                orientation="right"
                tickFormatter={formatYAxisCustomers}
                tickLine={false}
                axisLine={false}
              />
              <Tooltip
                formatter={(value: number | string | Array<number | string> | undefined, name: string | undefined) => {
                  const num = Number(value ?? 0);
                  if (name === '売上高' || name === '目標売上') {
                    return [`¥${num.toLocaleString()}`, name];
                  }
                  if (name === '来店客数') {
                    return [`${num.toLocaleString()} 人`, name];
                  }
                  return [num.toLocaleString(), name ?? ''];
                }}
                labelFormatter={(label) => `${label}の実績`}
              />
              <Legend verticalAlign="top" height={36} />
              <Bar
                yAxisId="salesAxis"
                dataKey="sales"
                name="売上高"
                fill={THEME_COLORS.sales}
                radius={[4, 4, 0, 0]}
                maxBarSize={48}
              />
              <Line
                yAxisId="salesAxis"
                type="monotone"
                dataKey="targetSales"
                name="目標売上"
                stroke={THEME_COLORS.target}
                strokeWidth={2}
                strokeDasharray="4 4"
                dot={{ r: 3 }}
              />
              <Line
                yAxisId="custAxis"
                type="monotone"
                dataKey="customers"
                name="来店客数"
                stroke={THEME_COLORS.customers}
                strokeWidth={3}
                dot={{ r: 4, strokeWidth: 2, fill: THEME_COLORS.chartBg }}
              />
            </ComposedChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="chart-card">
        <div>
          <h2 className="chart-title">客単価（平均支出）推移</h2>
          <p className="chart-subtitle">顧客1人あたりの平均購入単価の推移</p>
        </div>
        <div className="chart-wrapper">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={data} margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
              <defs>
                <linearGradient id="avgSpendGrad" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor={THEME_COLORS.avgSpend} stopOpacity={0.4} />
                  <stop offset="95%" stopColor={THEME_COLORS.avgSpend} stopOpacity={0} />
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} />
              <XAxis dataKey="month" tickLine={false} />
              <YAxis
                domain={['auto', 'auto']}
                tickFormatter={formatYAxisAvgSpend}
                tickLine={false}
                axisLine={false}
              />
              <Tooltip
                formatter={(value: number | string | Array<number | string> | undefined) => [
                  `¥${Number(value ?? 0).toLocaleString()}`,
                  '客単価',
                ]}
                labelFormatter={(label) => `${label}の実績`}
              />
              <Area
                type="monotone"
                dataKey="avgSpend"
                stroke={THEME_COLORS.avgSpend}
                strokeWidth={2}
                fillOpacity={1}
                fill="url(#avgSpendGrad)"
              />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="chart-card">
        <div>
          <h2 className="chart-title">売上達成率推移</h2>
          <p className="chart-subtitle">各月の目標売上に対する達成度比較</p>
        </div>
        <div className="chart-wrapper">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart
              data={data.map((d) => ({
                month: d.month,
                rate: d.targetSales > 0 ? Math.round((d.sales / d.targetSales) * 100 * 10) / 10 : 0,
              }))}
              margin={{ top: 20, right: 20, bottom: 20, left: 20 }}
            >
              <defs>
                <linearGradient id="rateGrad" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor={THEME_COLORS.customers} stopOpacity={0.35} />
                  <stop offset="95%" stopColor={THEME_COLORS.customers} stopOpacity={0} />
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} />
              <XAxis dataKey="month" tickLine={false} />
              <YAxis
                domain={['dataMin - 5', 'dataMax + 5']}
                tickFormatter={(val: number) => `${Math.round(val)}%`}
                tickLine={false}
                axisLine={false}
              />
              <Tooltip
                formatter={(value: number | string | Array<number | string> | undefined) => [
                  `${Number(value ?? 0)}%`,
                  '達成率',
                ]}
                labelFormatter={(label) => `${label}の実績`}
              />
              <Area
                type="monotone"
                dataKey="rate"
                stroke={THEME_COLORS.customers}
                strokeWidth={2}
                fillOpacity={1}
                fill="url(#rateGrad)"
              />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

export default ChartsView;

import { FC, useState, useMemo } from 'react';
import { ArrowUpDown, ArrowUp, ArrowDown } from 'lucide-react';
import { MonthlyData } from '../types';

interface DataTableProps {
  data?: MonthlyData[];
}

type SortColumn = 'month' | 'sales' | 'targetSales' | 'achieveRate' | 'customers' | 'avgSpend';
type SortDirection = 'asc' | 'desc';

interface TableRowData extends MonthlyData {
  achieveRate: number;
}

const sortBtnStyle: React.CSSProperties = {
  background: 'transparent',
  border: 'none',
  color: 'inherit',
  font: 'inherit',
  padding: 0,
  cursor: 'pointer',
  display: 'inline-flex',
  alignItems: 'center',
  outline: 'none',
};

const DataTable: FC<DataTableProps> = ({ data = [] }) => {
  const [sortColumn, setSortColumn] = useState<SortColumn>('month');
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc');

  const rows = useMemo<TableRowData[]>(() => {
    return data.map((d) => ({
      ...d,
      achieveRate: d.targetSales > 0 ? Math.round((d.sales / d.targetSales) * 100) : 0,
    }));
  }, [data]);

  const sortedRows = useMemo(() => {
    return [...rows].sort((a, b) => {
      let comparison = 0;
      if (sortColumn === 'month') {
        const aMonth = parseInt(a.month, 10) || 0;
        const bMonth = parseInt(b.month, 10) || 0;
        comparison = aMonth - bMonth;
      } else {
        comparison = a[sortColumn] - b[sortColumn];
      }
      return sortDirection === 'asc' ? comparison : -comparison;
    });
  }, [rows, sortColumn, sortDirection]);

  const handleSort = (column: SortColumn) => {
    if (sortColumn === column) {
      setSortDirection((prev) => (prev === 'asc' ? 'desc' : 'asc'));
    } else {
      setSortColumn(column);
      setSortDirection('desc');
    }
  };

  const renderSortIcon = (column: SortColumn) => {
    if (sortColumn !== column) {
      return <ArrowUpDown size={14} style={{ opacity: 0.5, marginLeft: 4 }} />;
    }
    return sortDirection === 'asc' ? (
      <ArrowUp size={14} style={{ color: 'var(--accent-primary)', marginLeft: 4 }} />
    ) : (
      <ArrowDown size={14} style={{ color: 'var(--accent-primary)', marginLeft: 4 }} />
    );
  };

  return (
    <div className="table-card">
      <div>
        <h2 className="chart-title">月次実績一覧</h2>
        <p className="chart-subtitle">各月の売上、目標、来店客数、客単価および達成率の一覧詳細</p>
      </div>

      <div className="table-wrapper">
        <table className="data-table">
          <thead>
            <tr>
              <th className="th-cell">
                <button
                  type="button"
                  className="th-sort-btn"
                  style={sortBtnStyle}
                  onClick={() => handleSort('month')}
                  aria-label="年月で並び替え"
                >
                  <span>年月</span>
                  {renderSortIcon('month')}
                </button>
              </th>
              <th className="th-cell td-num">
                <button
                  type="button"
                  className="th-sort-btn"
                  style={{ ...sortBtnStyle, justifyContent: 'flex-end', width: '100%' }}
                  onClick={() => handleSort('sales')}
                  aria-label="実績売上で並び替え"
                >
                  <span>実績売上 (円)</span>
                  {renderSortIcon('sales')}
                </button>
              </th>
              <th className="th-cell td-num">
                <button
                  type="button"
                  className="th-sort-btn"
                  style={{ ...sortBtnStyle, justifyContent: 'flex-end', width: '100%' }}
                  onClick={() => handleSort('targetSales')}
                  aria-label="目標売上で並び替え"
                >
                  <span>目標売上 (円)</span>
                  {renderSortIcon('targetSales')}
                </button>
              </th>
              <th className="th-cell">
                <button
                  type="button"
                  className="th-sort-btn"
                  style={sortBtnStyle}
                  onClick={() => handleSort('achieveRate')}
                  aria-label="達成率で並び替え"
                >
                  <span>達成率</span>
                  {renderSortIcon('achieveRate')}
                </button>
              </th>
              <th className="th-cell td-num">
                <button
                  type="button"
                  className="th-sort-btn"
                  style={{ ...sortBtnStyle, justifyContent: 'flex-end', width: '100%' }}
                  onClick={() => handleSort('customers')}
                  aria-label="客数で並び替え"
                >
                  <span>客数 (人)</span>
                  {renderSortIcon('customers')}
                </button>
              </th>
              <th className="th-cell td-num">
                <button
                  type="button"
                  className="th-sort-btn"
                  style={{ ...sortBtnStyle, justifyContent: 'flex-end', width: '100%' }}
                  onClick={() => handleSort('avgSpend')}
                  aria-label="客単価で並び替え"
                >
                  <span>客単価 (円)</span>
                  {renderSortIcon('avgSpend')}
                </button>
              </th>
            </tr>
          </thead>
          <tbody>
            {sortedRows.map((row) => {
              const progressWidth = Math.max(0, Math.min(row.achieveRate, 100));
              const isOverTarget = row.achieveRate >= 100;
              const fillBg = isOverTarget ? 'var(--accent-emerald)' : 'var(--accent-primary)';
              const badgeClass = isOverTarget ? 'kpi-badge kpi-badge-positive' : 'kpi-badge kpi-badge-negative';

              return (
                <tr key={row.month}>
                  <td className="td-cell header-title" style={{ fontSize: '0.875rem' }}>
                    {row.month}
                  </td>
                  <td className="td-cell td-num">¥{row.sales.toLocaleString()}</td>
                  <td className="td-cell td-num header-subtitle">
                    ¥{row.targetSales.toLocaleString()}
                  </td>
                  <td className="td-cell">
                    <div className="progress-bar-container">
                      <div className="progress-track">
                        <div
                          className="progress-fill"
                          style={{
                            width: `${progressWidth}%`,
                            backgroundColor: fillBg,
                          }}
                        />
                      </div>
                      <span className={badgeClass}>
                        {row.achieveRate}%
                      </span>
                    </div>
                  </td>
                  <td className="td-cell td-num">{row.customers.toLocaleString()}</td>
                  <td className="td-cell td-num">¥{row.avgSpend.toLocaleString()}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default DataTable;

import { FC, useState, useMemo } from 'react';
import { SlidersHorizontal, RotateCcw } from 'lucide-react';
import { MonthlyData, PeriodFilterType, FilterOption, SummaryCardData, SimulationParams } from './types';
import KpiCards from './components/KpiCards';
import ChartsView from './components/ChartsView';
import DataTable from './components/DataTable';

const BASE_MONTHLY_DATA: MonthlyData[] = [
  { month: '1月', sales: 4200000, customers: 1400, avgSpend: 3000, targetSales: 4000000 },
  { month: '2月', sales: 3850000, customers: 1250, avgSpend: 3080, targetSales: 3900000 },
  { month: '3月', sales: 4950000, customers: 1550, avgSpend: 3193, targetSales: 4500000 },
  { month: '4月', sales: 4600000, customers: 1420, avgSpend: 3239, targetSales: 4500000 },
  { month: '5月', sales: 5120000, customers: 1580, avgSpend: 3240, targetSales: 4800000 },
  { month: '6月', sales: 4400000, customers: 1380, avgSpend: 3188, targetSales: 4500000 },
  { month: '7月', sales: 5350000, customers: 1620, avgSpend: 3302, targetSales: 5000000 },
  { month: '8月', sales: 5680000, customers: 1710, avgSpend: 3321, targetSales: 5200000 },
  { month: '9月', sales: 4820000, customers: 1460, avgSpend: 3301, targetSales: 4800000 },
  { month: '10月', sales: 5150000, customers: 1530, avgSpend: 3366, targetSales: 5000000 },
  { month: '11月', sales: 5400000, customers: 1580, avgSpend: 3417, targetSales: 5100000 },
  { month: '12月', sales: 6250000, customers: 1780, avgSpend: 3511, targetSales: 5800000 },
];

const FILTER_OPTIONS: FilterOption[] = [
  { label: '全期間 (1-12月)', value: 'all' },
  { label: '上期 (1-6月)', value: 'first-half' },
  { label: '下期 (7-12月)', value: 'second-half' },
  { label: '直近3ヶ月', value: 'last-3' },
];

const App: FC = () => {
  const [period, setPeriod] = useState<PeriodFilterType>('all');
  const [simParams, setSimParams] = useState<SimulationParams>({
    customerRate: 0,
    spendRate: 0,
  });

  const periodFilteredData = useMemo(() => {
    switch (period) {
      case 'first-half':
        return BASE_MONTHLY_DATA.slice(0, 6);
      case 'second-half':
        return BASE_MONTHLY_DATA.slice(6, 12);
      case 'last-3':
        return BASE_MONTHLY_DATA.slice(-3);
      case 'all':
      default:
        return BASE_MONTHLY_DATA;
    }
  }, [period]);

  const simulatedData = useMemo(() => {
    const custMultiplier = 1 + simParams.customerRate / 100;
    const spendMultiplier = 1 + simParams.spendRate / 100;

    return periodFilteredData.map((d) => {
      const customers = Math.round(d.customers * custMultiplier);
      const avgSpend = Math.round(d.avgSpend * spendMultiplier);
      const sales = Math.round(customers * avgSpend);
      return {
        ...d,
        customers,
        avgSpend,
        sales,
      };
    });
  }, [periodFilteredData, simParams]);

  const kpiCards = useMemo<SummaryCardData[]>(() => {
    const totalSales = simulatedData.reduce((acc, cur) => acc + cur.sales, 0);
    const totalCustomers = simulatedData.reduce((acc, cur) => acc + cur.customers, 0);
    const avgSpend = totalCustomers > 0 ? Math.round(totalSales / totalCustomers) : 0;
    const totalTarget = simulatedData.reduce((acc, cur) => acc + cur.targetSales, 0);

    const salesAchievementRate = totalTarget > 0 ? ((totalSales - totalTarget) / totalTarget) * 100 : 0;
    const achieveRatePercent = totalTarget > 0 ? Math.round((totalSales / totalTarget) * 100) : 0;
    const count = simulatedData.length;
    const avgCustPerMonth = count > 0 ? Math.round(totalCustomers / count).toLocaleString() : '0';

    let custChangeRate = 0;
    let spendChangeRate = 0;
    if (simulatedData.length >= 2) {
      const latest = simulatedData[simulatedData.length - 1];
      const prev = simulatedData[simulatedData.length - 2];
      custChangeRate = prev.customers > 0 ? ((latest.customers - prev.customers) / prev.customers) * 100 : 0;
      spendChangeRate = prev.avgSpend > 0 ? ((latest.avgSpend - prev.avgSpend) / prev.avgSpend) * 100 : 0;
    }

    return [
      {
        title: '期間合計売上高',
        value: `¥${(totalSales / 10000).toLocaleString(undefined, { maximumFractionDigits: 1 })}`,
        unit: '万円',
        subValue: `目標: ¥${(totalTarget / 10000).toLocaleString(undefined, { maximumFractionDigits: 1 })}万円 (達成率 ${achieveRatePercent}%)`,
        changeRate: salesAchievementRate,
        isPositive: salesAchievementRate >= 0,
        iconName: 'sales',
      },
      {
        title: '期間総来客数',
        value: totalCustomers.toLocaleString(),
        unit: '人',
        subValue: `月平均: ${avgCustPerMonth}人 / 直近推移`,
        changeRate: custChangeRate,
        isPositive: custChangeRate >= 0,
        iconName: 'customers',
      },
      {
        title: '期間平均客単価',
        value: `¥${avgSpend.toLocaleString()}`,
        unit: '円/人',
        subValue: '1顧客あたりの平均利用額',
        changeRate: spendChangeRate,
        isPositive: spendChangeRate >= 0,
        iconName: 'avgSpend',
      },
    ];
  }, [simulatedData]);

  const handleCustChange = (val: number) => {
    const clamped = Math.max(-30, Math.min(30, isNaN(val) ? 0 : val));
    setSimParams((prev) => ({ ...prev, customerRate: clamped }));
  };

  const handleSpendChange = (val: number) => {
    const clamped = Math.max(-20, Math.min(20, isNaN(val) ? 0 : val));
    setSimParams((prev) => ({ ...prev, spendRate: clamped }));
  };

  const handleResetSimulation = () => {
    setSimParams({
      customerRate: 0,
      spendRate: 0,
    });
  };

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <div className="header-title-group">
          <h1 className="header-title">店舗・事業KPIダッシュボード</h1>
          <p className="header-subtitle">
            売上・客数・平均単価の月次推移およびシミュレーション分析
          </p>
        </div>

        <div className="filter-bar">
          {FILTER_OPTIONS.map((opt) => {
            const isActive = period === opt.value;
            const btnClass = isActive ? 'filter-btn filter-btn-active' : 'filter-btn';
            return (
              <button
                key={opt.value}
                className={btnClass}
                onClick={() => setPeriod(opt.value)}
              >
                {opt.label}
              </button>
            );
          })}
        </div>
      </header>

      <section className="sim-panel">
        <div className="sim-title">
          <div className="sim-title-label">
            <SlidersHorizontal size={16} />
            <span>売上影響シミュレーション（客数・客単価の増減感度）</span>
          </div>
          <button
            type="button"
            className="sim-reset-btn"
            onClick={handleResetSimulation}
            aria-label="シミュレーションを初期値にリセット"
          >
            <RotateCcw size={13} />
            <span>リセット</span>
          </button>
        </div>
        <div className="sim-controls">
          <div className="sim-slider-group">
            <label className="sim-label" htmlFor="cust-slider">客数変動率 (-30%〜+30%):</label>
            <input
              id="cust-slider"
              type="range"
              min="-30"
              max="30"
              step="1"
              value={simParams.customerRate}
              onChange={(e) => handleCustChange(Number(e.target.value))}
              className="sim-slider"
            />
            <div className="sim-input-group">
              <input
                id="cust-number-input"
                type="number"
                min="-30"
                max="30"
                step="1"
                value={simParams.customerRate}
                onChange={(e) => handleCustChange(Number(e.target.value))}
                className="sim-number-input"
                aria-label="客数変動率の直接数値入力"
              />
              <span className="sim-val-unit">%</span>
            </div>
          </div>

          <div className="sim-slider-group">
            <label className="sim-label" htmlFor="spend-slider">客単価変動率 (-20%〜+20%):</label>
            <input
              id="spend-slider"
              type="range"
              min="-20"
              max="20"
              step="1"
              value={simParams.spendRate}
              onChange={(e) => handleSpendChange(Number(e.target.value))}
              className="sim-slider"
            />
            <div className="sim-input-group">
              <input
                id="spend-number-input"
                type="number"
                min="-20"
                max="20"
                step="1"
                value={simParams.spendRate}
                onChange={(e) => handleSpendChange(Number(e.target.value))}
                className="sim-number-input"
                aria-label="客単価変動率の直接数値入力"
              />
              <span className="sim-val-unit">%</span>
            </div>
          </div>
        </div>
      </section>

      <KpiCards cards={kpiCards} />

      <ChartsView data={simulatedData} />

      <DataTable data={simulatedData} />
    </div>
  );
};

export default App;
